'use strict';
const DATA=JSON.parse(document.getElementById('manualdata').textContent);
const $=id=>document.getElementById(id);
const escapeHTML=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=value=>Number(value).toLocaleString(undefined,{maximumFractionDigits:4});
const human=name=>String(name).replace(/[-_]/g,' ').replace(/\b\w/g,c=>c.toUpperCase());
const maps={chapter:new Map(DATA.chapters.map(x=>[x.id,x])),topic:new Map(DATA.topics.map(x=>[x.id,x])),recipe:new Map(DATA.reference.recipes.map(x=>[x.name,x])),tech:new Map(DATA.reference.technologies.map(x=>[x.name,x])),entity:new Map(DATA.reference.entities.map(x=>[x.name,x])),item:new Map(DATA.reference.items.map(x=>[x.name,x])),fluid:new Map(DATA.reference.fluids.map(x=>[x.name,x]))};
const phaseNames={BEGIN:'01 · Getting started',EARLY:'02 · Early factory',MID:'03 · Middle game',LATE:'04 · Late game',FINISH:'05 · First launch',ADVANCED:'06 · Optional deep systems',REFERENCE:'07 · Working reference'};
const coreLinks=[['home','Learning map'],['search','Search everything'],['library','Topic library'],['controls','Keyboard & mouse'],['recipes','Recipes & ingredients'],['technology','Technology tree'],['machines','Machines, items & fluids'],['calculator','Production calculators'],['diagrams','Visual playground'],['help','Troubleshooting'],['glossary','Glossary'],['whatsnew','Current-version tools'],['sources','Official sources'],['audit','Audit & coverage']];
const progressKeys=new Set(DATA.chapters.flatMap(ch=>[...ch.steps.map((_,i)=>ch.id+':'+i),...ch.checks.map((_,i)=>ch.id+':quiz'+i)]));
let route='home',query='',category='All',scope='Base',controlLevel='All',catalogKind='entity',resultLimit=40,stepIndex=0;
let progress={},prefs={textSize:'100',highContrast:false,stepMode:false,lastLesson:'setup'};
function isObject(x){return x!==null&&typeof x==='object'&&!Array.isArray(x)}
function validateProgress(value){
 if(!isObject(value))throw new Error('Progress must be an object.');
 const clean={};
 for(const [key,checked] of Object.entries(value)){
  if(!progressKeys.has(key)||typeof checked!=='boolean')throw new Error('Unknown step or invalid checkbox value.');
  clean[key]=checked;
 }
 return clean;
}
function validatePreferences(value){
 if(!isObject(value))throw new Error('Reading options must be an object.');
 const clean={...prefs};
 if(value.textSize!==undefined){if(!['100','115','130'].includes(String(value.textSize)))throw new Error('Invalid text size.');clean.textSize=String(value.textSize)}
 for(const key of ['highContrast','stepMode'])if(value[key]!==undefined){if(typeof value[key]!=='boolean')throw new Error('Invalid reading option.');clean[key]=value[key]}
 if(value.lastLesson!==undefined){if(!maps.chapter.has(value.lastLesson))throw new Error('Unknown last lesson.');clean.lastLesson=value.lastLesson}
 return clean;
}
const notices={};
function notice(key,message){if(message)notices[key]=message;else delete notices[key];$('storageNotice').textContent=Object.values(notices).join(' ');$('storageNotice').hidden=!Object.keys(notices).length}
function save(key,value){try{localStorage.setItem(key,JSON.stringify(value));notice(key,'');return true}catch(_){notice(key,'This browser cannot save locally. Export progress before closing the manual.');return false}}
function persist(){return save('factorio_2_1_24_progress',progress)}
try{progress=validateProgress(JSON.parse(localStorage.getItem('factorio_2_1_24_progress')||'{}'))}catch(_){notice('factorio_2_1_24_progress','Saved progress could not be loaded. Import a valid backup or export your current work before closing.')}
try{prefs=validatePreferences(JSON.parse(localStorage.getItem('factorio_2_1_24_preferences')||'{}'))}catch(_){notice('factorio_2_1_24_preferences','Reading options could not be loaded. Default options are in use.')}
function applyPreferences(){document.documentElement.style.setProperty('--text-scale',Number(prefs.textSize)/100);document.body.classList.toggle('high-contrast',prefs.highContrast);$('textSize').value=prefs.textSize;$('highContrast').checked=prefs.highContrast;$('stepMode').checked=prefs.stepMode}
function readLocation(){
 try{
  const [raw,params='']=location.hash.slice(1).split('?');
  const path=decodeURIComponent(raw||'home');
  const parts=path.split('/');
  if(coreLinks.some(([id])=>id===path)||maps.chapter.has(path))return {route:path,query:new URLSearchParams(params).get('q')||'',recipe:new URLSearchParams(params).get('recipe'),scope:new URLSearchParams(params).get('scope')};
  if(parts.length===2&&maps[parts[0]]?.has(parts[1]))return {route:path,query:''};
 }catch(_){}
 return {route:'home',query:''};
}
function nav(to,search=''){
 const [path,parameters='']=to.split('?');const hash=encodeURI(path)+(search?'?q='+encodeURIComponent(search):(parameters?'?'+parameters:''));
 if(location.hash.slice(1)===hash){setRoute(readLocation(),true);return}
 location.hash=hash;
}
function setRoute(state,focus=false){route=state.route;query=state.query;if(state.recipe&&maps.recipe.has(state.recipe)){calc.recipe=state.recipe;calc.product='';calc.productivity=0}if(['Base','Expansion','Editor / debug','All'].includes(state.scope))scope=state.scope;category='All';resultLimit=40;stepIndex=0;if(maps.chapter.has(route)){prefs.lastLesson=route;save('factorio_2_1_24_preferences',prefs);const ch=maps.chapter.get(route);const next=ch.steps.findIndex((_,i)=>!progress[ch.id+':'+i]);stepIndex=next<0?0:next}render();document.body.classList.remove('nav-open');$('lessonsBtn').setAttribute('aria-expanded','false');window.scrollTo(0,0);if(focus)$('content').querySelector('h1')?.focus({preventScroll:true})}
function link(to,label,classes=''){return `<a class="${classes}" data-to="${escapeHTML(to)}" href="#${escapeHTML(to)}">${escapeHTML(label)}</a>`}
function heading(eyebrow,title,description=''){return `<header class="pagehead"><div class="eyebrow">${escapeHTML(eyebrow)}</div><h1 tabindex="-1">${escapeHTML(title)}</h1><p class="lead">${escapeHTML(description)}</p></header>`}
function list(items){return `<ul>${items.map(x=>`<li>${escapeHTML(x)}</li>`).join('')}</ul>`}
function panel(title,body){return `<section class="panel"><h2>${escapeHTML(title)}</h2>${body}</section>`}
function sourceLinks(ids){return `<div class="refs">${[...new Set(ids)].map(id=>DATA.sources[id]?`<a href="${escapeHTML(DATA.sources[id][1])}" target="_blank" rel="noopener noreferrer">${escapeHTML(DATA.sources[id][0])} ↗</a>`:'').join('')}</div>`}
function topicLinks(ids){return `<div class="topic-nav">${ids.map(id=>link('topic/'+id,maps.topic.get(id)?.title||human(id),'pill')).join('')}</div>`}
function visited(ch){return ch.steps.filter((_,i)=>progress[ch.id+':'+i]===true).length}
function stats(){const total=DATA.chapters.reduce((n,ch)=>n+ch.steps.length,0),done=DATA.chapters.reduce((n,ch)=>n+visited(ch),0);return {total,done,pct:Math.round(100*done/total)}}
function updateProgress(){const st=stats();$('sidebarprogress').style.width=st.pct+'%';$('sidebarpct').textContent=`${st.done}/${st.total} steps (${st.pct}%)`;$('sidebarprogress').parentElement.setAttribute('aria-valuenow',st.pct);if(maps.chapter.has(route)){const ch=maps.chapter.get(route);const el=$('lessonProgress');if(el)el.textContent=`${visited(ch)} of ${ch.steps.length} steps checked`;const bar=$('lessonBar');if(bar)bar.style.width=100*visited(ch)/ch.steps.length+'%'}document.querySelectorAll('[data-lesson-count]').forEach(el=>{const ch=maps.chapter.get(el.dataset.lessonCount);el.textContent=visited(ch)===ch.steps.length?'✓':`${visited(ch)}/${ch.steps.length}`})}
function totalNav(){const active=route.split('/')[0];$('coreNav').innerHTML=coreLinks.map(([id,label])=>link(id,label,'side-button')).join('');let last='';$('lessonNav').innerHTML=DATA.chapters.map((ch,i)=>{const phase=ch.phase!==last?`<div class="side-label">${escapeHTML(phaseNames[ch.phase])}</div>`:'';last=ch.phase;return phase+link(ch.id,`${i+1}. ${ch.title}`,'side-button')+`<small class="tiny lesson-count" data-lesson-count="${ch.id}"></small>`}).join('');document.querySelectorAll('.side [data-to]').forEach(el=>{const match=el.dataset.to===route||(el.dataset.to==='library'&&active==='topic')||(el.dataset.to==='recipes'&&active==='recipe')||(el.dataset.to==='technology'&&active==='tech')||(el.dataset.to==='machines'&&['entity','item','fluid'].includes(active));if(match)el.setAttribute('aria-current','page')});updateProgress()}
function box(x,y,w,h,t,color='#263949'){return `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="11" fill="${color}" stroke="#7692a5" stroke-width="1.5"/><text x="${x+w/2}" y="${y+h/2+5}" text-anchor="middle" fill="#f1f6fa" font-family="system-ui" font-size="20" font-weight="650">${escapeHTML(t)}</text>`}
function arrow(x1,y1,x2,y2,color='#f2c979'){return `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${color}" stroke-width="4" marker-end="url(#arr)"/>`}
function caption(x,y,t){return `<text x="${x}" y="${y}" text-anchor="middle" fill="#b9cbd4" font-size="17" font-family="system-ui">${escapeHTML(t)}</text>`}
