 if(el.dataset.rail){$('railOutcome').innerHTML=el.dataset.rail==='chain'?'<strong>Chain: WAIT before entering.</strong> Its chosen path cannot exit into the occupied block.':'<strong>Regular: ENTER the empty crossing block.</strong> The train may then wait at the red exit and obstruct the junction.';return}
 if(el.dataset.quiz){const q=quizzes.find(q=>q.id===el.dataset.quiz);const correct=Number(el.dataset.choice)===q.answer;$('quiz-'+q.id).textContent=(correct?'Correct. ':'Review this: ')+q.explanation;document.querySelectorAll(`[data-quiz="${q.id}"]`).forEach(b=>b.setAttribute('aria-pressed',b===el));return}
