$('importBtn').onclick=()=>$('importFile').click();
$('importFile').onchange=async event=>{
 const file=event.target.files[0];if(!file)return;
 try{
  if(file.size>2*1024*1024)throw new Error('This is too large to be a manual progress export.');
  const obj=JSON.parse(await file.text());
  if(!isObject(obj)||obj.manualVersion!==DATA.meta.version)throw new Error('Choose a progress export for version '+DATA.meta.version+'.');
  const imported=validateProgress(obj.progress),options=obj.preferences===undefined?prefs:validatePreferences(obj.preferences);
  // Validate the whole import before replacing either progress or reading options.
  progress=imported;prefs=options;persist();save('factorio_2_1_24_preferences',prefs);applyPreferences();render();alert('Progress imported.');
 }catch(error){alert('Could not import progress. '+error.message)}finally{event.target.value=''}
};
let printDetails=[],printHidden=[];
